     286:         return ret;
     287:     }
     288:     for (i = 0; i < length; i++, p++) {
     289:         if (*p == 0x80 && (!i || !(p[-1] & 0x80))) {
     290:             ERR_raise(ERR_LIB_ASN1, ASN1_R_INVALID_OBJECT_ENCODING);
     291:             return NULL;
     292:         }
     293:     }
     294: 
     295:     if ((a == NULL) || ((*a) == NULL) || !((*a)->flags & ASN1_OBJECT_FLAG_DYNAMIC)) {
     296:         if ((ret = ossl_asn1_object_new()) == NULL)
     297:             return NULL;
     298:     } else {
     299:         ret = (*a);
     300:     }
