     318:         OPENSSL_free((char *)ret->sn);
     319:         OPENSSL_free((char *)ret->ln);
     320:         ret->flags &= ~ASN1_OBJECT_FLAG_DYNAMIC_STRINGS;
     321:     }
     322:     /* reattach data to object, after which it remains const */
     323:     ret->data = data;
     324:     ret->length = length;
     325:     ret->sn = NULL;
     326:     ret->ln = NULL;
     327:     /* ret->flags=ASN1_OBJECT_FLAG_DYNAMIC; we know it is dynamic */
     328:     p += length;
     329: 
     330:     if (a != NULL)
     331:         (*a) = ret;
