     270: static int poll_for_response(OSSL_CMP_CTX *ctx, int sleep, int rid,
     271:     OSSL_CMP_MSG **rep, int *checkAfter)
     272: {
     273:     OSSL_CMP_MSG *preq = NULL;
     274:     OSSL_CMP_MSG *prep = NULL;
     275: 
     276:     ossl_cmp_info(ctx,
     277:         "received 'waiting' PKIStatus, starting to poll for response");
     278:     *rep = NULL;
     279:     for (;;) {
     280:         int bak = ctx->status;
     281: 
     282:         ctx->status = OSSL_CMP_PKISTATUS_request;
>>   283:         if ((preq = ossl_cmp_pollReq_new(ctx, rid)) == NULL)
     284:             goto err;
     285: 
>>   286:         if (!send_receive_check(ctx, preq, &prep, OSSL_CMP_PKIBODY_POLLREP))
     287:             goto err;
     288:         ctx->status = bak;
     289: 
     290:         /* handle potential pollRep */
>>   291:         if (OSSL_CMP_MSG_get_bodytype(prep) == OSSL_CMP_PKIBODY_POLLREP) {
     292:             OSSL_CMP_POLLREPCONTENT *prc = prep->body->value.pollRep;
     293:             OSSL_CMP_POLLREP *pollRep = NULL;
     294:             int64_t check_after;
     295:             char str[OSSL_CMP_PKISI_BUFLEN];
     296:             int len;
     297: 
     298:             if (sk_OSSL_CMP_POLLREP_num(prc) > 1) {
     299:                 ERR_raise(ERR_LIB_CMP, CMP_R_MULTIPLE_RESPONSES_NOT_SUPPORTED);
     300:                 goto err;
     301:             }
     302:             pollRep = ossl_cmp_pollrepcontent_get0_pollrep(prc, rid);
     303:             if (pollRep == NULL)
     304:                 goto err;
     305: 
     306:             if (!ASN1_INTEGER_get_int64(&check_after, pollRep->checkAfter)) {
     307:                 ERR_raise(ERR_LIB_CMP, CMP_R_BAD_CHECKAFTER_IN_POLLREP);
     308:                 goto err;
     309:             }
     310:             if (check_after < 0 || (uint64_t)check_after > (sleep ? ULONG_MAX / 1000 : INT_MAX)) {
     311:                 ERR_raise(ERR_LIB_CMP, CMP_R_CHECKAFTER_OUT_OF_RANGE);
     312:                 if (BIO_snprintf(str, OSSL_CMP_PKISI_BUFLEN, "value = %jd",
     313:                         check_after)
     314:                     >= 0)
     315:                     ERR_add_error_data(1, str);
     316:                 goto err;
     317:             }
     318: 
     319:             if (pollRep->reason == NULL
     320:                 || (len = BIO_snprintf(str, OSSL_CMP_PKISI_BUFLEN,
     321:                         " with reason = '"))
     322:                     < 0) {
     323:                 *str = '\0';
     324:             } else {
     325:                 char *text = ossl_sk_ASN1_UTF8STRING2text(pollRep->reason, ", ",
     326:                     sizeof(str) - len - 2);
     327: 
     328:                 if (text == NULL
     329:                     || BIO_snprintf(str + len, sizeof(str) - len,
     330:                            "%s'", text)
     331:                         < 0)
     332:                     *str = '\0';
     333:                 OPENSSL_free(text);
     334:             }
     335:             ossl_cmp_log2(INFO, ctx,
     336:                 "received polling response%s; checkAfter = %ld seconds",
     337:                 str, check_after);
     338: 
     339:             if (ctx->total_timeout != 0) { /* timeout is not infinite */
     340:                 const int exp = OSSL_CMP_EXPECTED_RESP_TIME;
     341:                 int64_t time_left = (int64_t)(ctx->end_time - exp - time(NULL));
     342: 
     343:                 if (time_left <= 0) {
     344:                     ctx->status = OSSL_CMP_PKISTATUS_trans;
     345:                     ERR_raise(ERR_LIB_CMP, CMP_R_TOTAL_TIMEOUT);
     346:                     goto err;
     347:                 }
     348:                 if (time_left < check_after)
     349:                     check_after = time_left;
     350:                 /* poll one last time just when timeout was reached */
     351:             }
     352: 
     353:             OSSL_CMP_MSG_free(preq);
     354:             preq = NULL;
     355:             OSSL_CMP_MSG_free(prep);
     356:             prep = NULL;
     357:             if (sleep) {
     358:                 OSSL_sleep((unsigned long)(1000 * check_after));
     359:             } else {
     360:                 if (checkAfter != NULL)
     361:                     *checkAfter = (int)check_after;
     362:                 return -1; /* exits the loop */
     363:             }
>>   364:         } else if (is_crep_with_waiting(prep, rid)
>>   365:             || ossl_cmp_is_error_with_waiting(prep)) {
     366:             /* received status must not be 'waiting' */
     367:             (void)ossl_cmp_exchange_error(ctx, OSSL_CMP_PKISTATUS_rejection,
     368:                 OSSL_CMP_CTX_FAILINFO_badRequest,
     369:                 "polling already started",
     370:                 0 /* errorCode */, NULL);
     371:             ERR_raise(ERR_LIB_CMP, CMP_R_UNEXPECTED_PKISTATUS);
     372:             goto err;
     373:         } else {
     374:             ossl_cmp_info(ctx, "received final response after polling");
>>   375:             if (!ossl_cmp_ctx_set1_first_senderNonce(ctx, NULL))
     376:                 goto err;
     377:             break;
     378:         }
     379:     }
>>   380:     if (prep == NULL)
     381:         goto err;
     382: 
     383:     OSSL_CMP_MSG_free(preq);
     384:     *rep = prep;
     385: 
     386:     return 1;
     387: err:
     388:     (void)ossl_cmp_ctx_set1_first_senderNonce(ctx, NULL);
     389:     OSSL_CMP_MSG_free(preq);
     390:     OSSL_CMP_MSG_free(prep);
     391:     return 0;
     392: }

