     611:         && req_type != OSSL_CMP_PKIBODY_ERROR) {
     612:         ERR_raise(ERR_LIB_CMP, CMP_R_EXPECTED_POLLREQ);
     613:         goto err;
     614:     }
     615: 
     616:     switch (req_type) {
     617:     case OSSL_CMP_PKIBODY_IR:
     618:     case OSSL_CMP_PKIBODY_CR:
     619:     case OSSL_CMP_PKIBODY_P10CR:
     620:     case OSSL_CMP_PKIBODY_KUR:
     621:     case OSSL_CMP_PKIBODY_RR:
     622:     case OSSL_CMP_PKIBODY_GENM:
     623:     case OSSL_CMP_PKIBODY_ERROR:
