     636:             goto err;
     637: 
     638:         if (srv_ctx->clean_transaction != NULL
     639:             && !srv_ctx->clean_transaction(srv_ctx, NULL)) {
     640:             ERR_raise(ERR_LIB_CMP, CMP_R_ERROR_PROCESSING_MESSAGE);
     641:             goto err;
     642:         }
     643: 
     644:         break;
     645:     default:
