     647:         if (ctx->transactionID == NULL) {
     648: #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
     649:             ERR_raise(ERR_LIB_CMP, CMP_R_UNEXPECTED_PKIBODY);
     650:             goto err;
     651: #endif
     652:         }
     653:     }
     654: 
     655:     req_verified = ossl_cmp_msg_check_update(ctx, req, unprotected_exception,
     656:         srv_ctx->acceptUnprotected);
