>>   670:             && (rsp = delayed_delivery(srv_ctx, req)) != NULL) {
     671:             goto err;
     672:         }
     673:         rsp = process_non_polling_request(srv_ctx, req);
     674:     }
     675: 
     676: err:
     677:     if (rsp == NULL) {
     678:         /* on error, try to respond with CMP error message to client */
