     530: static int cms_RecipientInfo_ktri_encrypt(const CMS_ContentInfo *cms,
     531:     CMS_RecipientInfo *ri)
     532: {
     533:     CMS_KeyTransRecipientInfo *ktri;
     534:     CMS_EncryptedContentInfo *ec;
     535:     EVP_PKEY_CTX *pctx;
     536:     unsigned char *ek = NULL;
     537:     size_t eklen;
     538:     const CMS_CTX *ctx = ossl_cms_get0_cmsctx(cms);
     539: 
     540:     int ret = 0;
     541: 
     542:     if (ri->type != CMS_RECIPINFO_TRANS) {
     543:         ERR_raise(ERR_LIB_CMS, CMS_R_NOT_KEY_TRANSPORT);
     544:         return 0;
     545:     }
     546:     ktri = ri->d.ktri;
     547:     ec = ossl_cms_get0_env_enc_content(cms);
     548: 
     549:     pctx = ktri->pctx;
     550: 
     551:     if (pctx) {
     552:         if (!ossl_cms_env_asn1_ctrl(ri, 0))
     553:             goto err;
     554:     } else {
     555:         pctx = EVP_PKEY_CTX_new_from_pkey(ossl_cms_ctx_get0_libctx(ctx),
     556:             ktri->pkey,
     557:             ossl_cms_ctx_get0_propq(ctx));
     558:         if (pctx == NULL)
     559:             return 0;
     560: 
     561:         if (EVP_PKEY_encrypt_init(pctx) <= 0)
     562:             goto err;
     563:     }
     564: 
     565:     if (EVP_PKEY_encrypt(pctx, NULL, &eklen, ec->key, ec->keylen) <= 0)
     566:         goto err;
     567: 
>>   568:     ek = OPENSSL_malloc(eklen);
     569:     if (ek == NULL)
     570:         goto err;
     571: 
>>   572:     if (EVP_PKEY_encrypt(pctx, ek, &eklen, ec->key, ec->keylen) <= 0)
     573:         goto err;
     574: 
     575:     ASN1_STRING_set0(ktri->encryptedKey, ek, (int)eklen);
     576:     ek = NULL;
     577: 
     578:     ret = 1;
     579: 
     580: err:
     581:     EVP_PKEY_CTX_free(pctx);
     582:     ktri->pctx = NULL;
     583:     OPENSSL_free(ek);
     584:     return ret;
     585: }

     346: static int cms_RecipientInfo_ktri_init(CMS_RecipientInfo *ri, X509 *recip,
     347:     EVP_PKEY *pk, unsigned int flags,
     348:     const CMS_CTX *ctx)
     349: {
     350:     CMS_KeyTransRecipientInfo *ktri;
     351:     int idtype;
     352: 
>>   353:     ri->d.ktri = M_ASN1_new_of(CMS_KeyTransRecipientInfo);
     354:     if (!ri->d.ktri)
     355:         return 0;
     356:     ri->encoded_type = ri->type = CMS_RECIPINFO_TRANS;
     357: 
     358:     ktri = ri->d.ktri;
     359:     ktri->cms_ctx = ctx;
     360: 
     361:     if (flags & CMS_USE_KEYID) {
     362:         ktri->version = 2;
     363:         idtype = CMS_RECIPINFO_KEYIDENTIFIER;
     364:     } else {
     365:         ktri->version = 0;
     366:         idtype = CMS_RECIPINFO_ISSUER_SERIAL;
