     379:     if (!EVP_PKEY_up_ref(pk)) {
     380:         X509_free(recip);
     381:         return 0;
     382:     }
     383: 
     384:     ktri->pkey = pk;
     385:     ktri->recip = recip;
     386: 
     387:     if (flags & CMS_KEY_PARAM) {
     388:         ktri->pctx = EVP_PKEY_CTX_new_from_pkey(ossl_cms_ctx_get0_libctx(ctx),
