    1053: static int cms_SignerInfo_content_sign(CMS_ContentInfo *cms,
    1054:     CMS_SignerInfo *si, BIO *chain,
    1055:     BIO *data,
    1056:     const unsigned char *md,
    1057:     unsigned int mdlen)
    1058: {
    1059:     EVP_MD_CTX *mctx = EVP_MD_CTX_new();
    1060:     int r = 0;
    1061:     EVP_PKEY_CTX *pctx = NULL;
    1062:     const CMS_CTX *ctx = ossl_cms_get0_cmsctx(cms);
    1063:     EVP_SIGNATURE *sig_alg = NULL;
    1064:     unsigned char *sig = NULL;
    1065: 
    1066:     if (mctx == NULL) {
    1067:         ERR_raise(ERR_LIB_CMS, ERR_R_CMS_LIB);
    1068:         return 0;
    1069:     }
    1070: 
    1071:     if (si->pkey == NULL) {
    1072:         ERR_raise(ERR_LIB_CMS, CMS_R_NO_PRIVATE_KEY);
    1073:         goto err;
    1074:     }
    1075: 
    1076:     if (!ossl_cms_DigestAlgorithm_find_ctx(mctx, chain, si->digestAlgorithm))
    1077:         goto err;
    1078:     /* Set SignerInfo algorithm details if we used custom parameter */
    1079:     if (si->pctx && !cms_sd_asn1_ctrl(si, 0))
    1080:         goto err;
    1081: 
    1082:     /*
    1083:      * If any signed attributes calculate and add messageDigest attribute
    1084:      */
    1085:     if (CMS_signed_get_attr_count(si) >= 0) {
    1086:         unsigned char computed_md[EVP_MAX_MD_SIZE];
    1087: 
    1088:         if (md == NULL) {
    1089:             if (!EVP_DigestFinal_ex(mctx, computed_md, &mdlen))
    1090:                 goto err;
    1091:             md = computed_md;
    1092:         }
    1093:         if (!CMS_signed_add1_attr_by_NID(si, NID_pkcs9_messageDigest,
    1094:                 V_ASN1_OCTET_STRING, md, mdlen))
    1095:             goto err;
    1096:         /* Copy content type across */
    1097:         if (!cms_set_si_contentType_attr(cms, si))
    1098:             goto err;
    1099: 
    1100:         if (!CMS_SignerInfo_sign(si))
    1101:             goto err;
    1102:     } else if (si->pctx) {
    1103:         size_t siglen;
    1104:         unsigned char computed_md[EVP_MAX_MD_SIZE];
    1105: 
    1106:         pctx = si->pctx;
    1107:         si->pctx = NULL;
    1108:         if (md == NULL) {
    1109:             if (!EVP_DigestFinal_ex(mctx, computed_md, &mdlen))
    1110:                 goto err;
    1111:             md = computed_md;
    1112:         }
    1113:         siglen = EVP_PKEY_get_size(si->pkey);
>>  1114:         if (siglen == 0 || (sig = OPENSSL_malloc(siglen)) == NULL)
    1115:             goto err;
>>  1116:         if (EVP_PKEY_sign(pctx, sig, &siglen, md, mdlen) <= 0)
    1117:             goto err;
    1118:         ASN1_STRING_set0(si->signature, sig, (int)siglen);
    1119:         sig = NULL;
    1120:     } else {
    1121:         OSSL_LIB_CTX *libctx = ossl_cms_ctx_get0_libctx(ctx);
    1122:         const char *algorithm;
    1123:         unsigned int siglen;
    1124:         int has_msg_update;
    1125: 
    1126:         if (md != NULL) {
    1127:             ERR_raise(ERR_LIB_CMS, CMS_R_OPERATION_UNSUPPORTED);
    1128:             goto err;
    1129:         }
    1130:         siglen = EVP_PKEY_get_size(si->pkey);
    1131:         if (siglen == 0 || (sig = OPENSSL_malloc(siglen)) == NULL)
    1132:             goto err;
    1133: 
    1134:         if ((algorithm = cms_mdless_signing(si->pkey)) != NULL) {
    1135:             size_t sig_len;
    1136: 
    1137:             if (!data) {
    1138:                 ERR_raise(ERR_LIB_CMS, CMS_R_NO_CONTENT);
    1139:                 goto err;
    1140:             }
    1141: 
    1142:             pctx = EVP_PKEY_CTX_new(si->pkey, NULL);
    1143:             if (!pctx)
    1144:                 goto err;
    1145: 
    1146:             sig_alg = EVP_SIGNATURE_fetch(libctx, algorithm, NULL);
    1147:             if (!sig_alg)
    1148:                 goto err;
    1149: 
    1150:             if (EVP_PKEY_sign_message_init(pctx, sig_alg, NULL) != 1)
    1151:                 goto err;
    1152: 
    1153:             sig_len = siglen;
    1154:             has_msg_update = EVP_SIGNATURE_has_message_update(sig_alg);
    1155:             if (cms_EVP_PKEY_sign(pctx, data, sig, &sig_len,
    1156:                     has_msg_update)
    1157:                 != 1)
    1158:                 goto err;
    1159:             siglen = (unsigned int)sig_len;
    1160:         } else {
    1161:             if (!EVP_SignFinal_ex(mctx, sig, &siglen, si->pkey, libctx,
    1162:                     ossl_cms_ctx_get0_propq(ctx))) {
    1163:                 ERR_raise(ERR_LIB_CMS, CMS_R_SIGNFINAL_ERROR);
    1164:                 goto err;
    1165:             }
    1166:         }
    1167:         ASN1_STRING_set0(si->signature, sig, siglen);
    1168:         sig = NULL;
    1169:     }
    1170: 
    1171:     r = 1;
    1172: 
    1173: err:
    1174:     OPENSSL_free(sig);
    1175:     EVP_MD_CTX_free(mctx);
    1176:     EVP_PKEY_CTX_free(pctx);
    1177:     EVP_SIGNATURE_free(sig_alg);
