     244: static char *dlfcn_name_converter(DSO *dso, const char *filename)
     245: {
     246:     char *translated;
     247:     int len, rsize, transform;
     248: 
     249:     len = strlen(filename);
     250:     rsize = len + 1;
     251:     transform = (strchr(filename, '/') == NULL);
     252:     if (transform) {
     253:         /* We will convert this to "%s.so" or "lib%s.so" etc */
     254:         rsize += strlen(DSO_EXTENSION); /* The length of ".so" */
     255:         if ((DSO_flags(dso) & DSO_FLAG_NAME_TRANSLATION_EXT_ONLY) == 0)
     256:             rsize += 3; /* The length of "lib" */
     257:     }
>>   258:     translated = OPENSSL_malloc(rsize);
     259:     if (translated == NULL) {
     260:         ERR_raise(ERR_LIB_DSO, DSO_R_NAME_TRANSLATION_FAILED);
     261:         return NULL;
     262:     }
     263:     if (transform) {
     264:         if ((DSO_flags(dso) & DSO_FLAG_NAME_TRANSLATION_EXT_ONLY) == 0)
     265:             BIO_snprintf(translated, rsize, "lib%s" DSO_EXTENSION, filename);
     266:         else
     267:             BIO_snprintf(translated, rsize, "%s" DSO_EXTENSION, filename);
     268:     } else {
     269:         BIO_snprintf(translated, rsize, "%s", filename);
     270:     }
     271:     return translated;
     272: }

     192: static char *dlfcn_merger(DSO *dso, const char *filespec1,
     193:     const char *filespec2)
     194: {
     195:     char *merged;
     196: 
     197:     if (!filespec1 && !filespec2) {
     198:         ERR_raise(ERR_LIB_DSO, ERR_R_PASSED_NULL_PARAMETER);
     199:         return NULL;
     200:     }
     201:     /*
     202:      * If the first file specification is a rooted path, it rules. same goes
     203:      * if the second file specification is missing.
     204:      */
     205:     if (!filespec2 || (filespec1 != NULL && filespec1[0] == '/')) {
     206:         merged = OPENSSL_strdup(filespec1);
     207:         if (merged == NULL)
     208:             return NULL;
     209:     }
     210:     /*
     211:      * If the first file specification is missing, the second one rules.
     212:      */
     213:     else if (!filespec1) {
     214:         merged = OPENSSL_strdup(filespec2);
     215:         if (merged == NULL)
     216:             return NULL;
     217:     } else {
     218:         /*
     219:          * This part isn't as trivial as it looks.  It assumes that the
     220:          * second file specification really is a directory, and makes no
     221:          * checks whatsoever.  Therefore, the result becomes the
     222:          * concatenation of filespec2 followed by a slash followed by
     223:          * filespec1.
     224:          */
     225:         int spec2len, len;
     226: 
     227:         spec2len = strlen(filespec2);
     228:         len = spec2len + strlen(filespec1);
     229: 
     230:         if (spec2len && filespec2[spec2len - 1] == '/') {
     231:             spec2len--;
     232:             len--;
     233:         }
>>   234:         merged = OPENSSL_malloc(len + 2);
     235:         if (merged == NULL)
     236:             return NULL;
     237:         strcpy(merged, filespec2);
     238:         merged[spec2len] = '/';
     239:         strcpy(&merged[spec2len + 1], filespec1);
     240:     }
     241:     return merged;
     242: }

