     474: static int grow_hashtable(HT *h, size_t oldsize)
     475: {
     476:     struct ht_mutable_data_st *newmd;
     477:     struct ht_mutable_data_st *oldmd = ossl_rcu_deref(&h->md);
     478:     CRYPTO_RCU_CB_ITEM *cbi = NULL;
     479:     int rc = 0;
