     492:     /* bucket list is always a power of 2 */
>>   493:     newmd->neighborhoods = alloc_new_neighborhood_list(oldsize * 2,
     494:         &newmd->neighborhood_ptr_to_free);
     495:     if (newmd->neighborhoods == NULL)
     496:         goto out_free;
     497: 
     498:     /* being a power of 2 makes for easy mask computation */
     499:     newmd->neighborhood_mask = (newsize - 1);
     500: 
     501:     /*
     502:      * Now we need to start rehashing entries
     503:      * Note we don't need to use atomics here as the new
     504:      * mutable data hasn't been published
     505:      */
     506:     for (oldi = 0; oldi < h->wpd.neighborhood_len; oldi++) {
     507:         PREFETCH_NEIGHBORHOOD(oldmd->neighborhoods[oldi + 1]);
     508:         for (oldj = 0; oldj < NEIGHBORHOOD_LEN; oldj++) {
     509:             oldv = oldmd->neighborhoods[oldi].entries[oldj].value;
     510:             if (oldv == NULL)
     511:                 continue;
     512:             oldhash = oldmd->neighborhoods[oldi].entries[oldj].hash;
     513:             newi = oldhash & newmd->neighborhood_mask;
     514:             rehashed = 0;
     515:             for (newj = 0; newj < NEIGHBORHOOD_LEN; newj++) {
     516:                 if (newmd->neighborhoods[newi].entries[newj].value == NULL) {
     517:                     newmd->neighborhoods[newi].entries[newj].value = oldv;
     518:                     newmd->neighborhoods[newi].entries[newj].hash = oldhash;
     519:                     rehashed = 1;
     520:                     break;
     521:                 }
     522:             }
     523:             if (rehashed == 0) {
     524:                 /* we ran out of space in a neighborhood, grow again */
     525:                 OPENSSL_free(newmd->neighborhood_ptr_to_free);
     526:                 OPENSSL_free(newmd);
     527:                 return grow_hashtable(h, newsize);
     528:             }
     529:         }
     530:     }
     531: 
     532:     /*
     533:      * Pre allocate the rcu callback item before assigning the newmd.
     534:      */
     535:     if (!h->config.no_rcu) {
     536:         cbi = ossl_rcu_cb_item_new();
     537:         if (cbi == NULL)
     538:             goto out_free;
     539:     }
     540: 
     541:     /*
     542:      * Now that our entries are all hashed into the new bucket list
     543:      * update our bucket_len and target_max_load
     544:      */
     545:     h->wpd.neighborhood_len = newsize;
     546: 
     547:     /*
     548:      * Now we replace the old mutable data with the new
     549:      */
     550:     if (!h->config.no_rcu) {
     551:         ossl_rcu_assign_ptr(&h->md, &newmd);
     552:         ossl_rcu_call(h->lock, cbi, free_old_neigh_table, oldmd);
     553:         h->wpd.need_sync = 1;
     554:     } else {
     555:         h->md = newmd;
     556:         free_old_neigh_table(oldmd);
     557:     }
     558:     /*
     559:      * And we're done
     560:      */
     561:     rc = 1;
     562: 
     563: out:
     564:     return rc;
     565: out_free:
