     659:     unsigned char ks_context[OSSL_HPKE_MAXSIZE];
     660:     size_t halflen = 0;
     661:     size_t pskidlen = 0;
     662:     const OSSL_HPKE_AEAD_INFO *aead_info = NULL;
     663:     const OSSL_HPKE_KDF_INFO *kdf_info = NULL;
