     708:     if (kctx == NULL) {
     709:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     710:         return 0;
     711:     }
     712:     pskidlen = (ctx->psk == NULL ? 0 : strlen(ctx->pskid));
     713:     /* full suite details as per RFC9180 sec 5.1 */
     714:     suitebuf[0] = ctx->suite.kem_id / 256;
     715:     suitebuf[1] = ctx->suite.kem_id % 256;
     716:     suitebuf[2] = ctx->suite.kdf_id / 256;
     717:     suitebuf[3] = ctx->suite.kdf_id % 256;
     718:     suitebuf[4] = ctx->suite.aead_id / 256;
     719:     suitebuf[5] = ctx->suite.aead_id % 256;
