     723:             suitebuf, sizeof(suitebuf),
     724:             OSSL_HPKE_PSKIDHASH_LABEL,
     725:             (unsigned char *)ctx->pskid, pskidlen)
     726:         != 1) {
     727:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     728:         goto err;
     729:     }
     730:     if (ossl_hpke_labeled_extract(kctx, ks_context + 1 + halflen, halflen,
     731:             NULL, 0, OSSL_HPKE_SEC51LABEL,
     732:             suitebuf, sizeof(suitebuf),
     733:             OSSL_HPKE_INFOHASH_LABEL,
     734:             (unsigned char *)info, infolen)
     735:         != 1) {
     736:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     737:         goto err;
     738:     }
     739:     ks_contextlen = 1 + 2 * halflen;
     740:     secretlen = kdf_info->Nh;
