     670:     /* only let this be done once */
     671:     if (ctx->exportersec != NULL) {
     672:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_SHOULD_NOT_HAVE_BEEN_CALLED);
     673:         return 0;
     674:     }
     675:     if (ossl_HPKE_KEM_INFO_find_id(ctx->suite.kem_id) == NULL) {
     676:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     677:         return 0;
     678:     }
     679:     aead_info = ossl_HPKE_AEAD_INFO_find_id(ctx->suite.aead_id);
     680:     if (aead_info == NULL) {
     681:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     682:         return 0;
     683:     }
     684:     kdf_info = ossl_HPKE_KDF_INFO_find_id(ctx->suite.kdf_id);
     685:     if (kdf_info == NULL) {
     686:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     687:         return 0;
     688:     }
     689:     mdname = kdf_info->mdname;
     690:     /* create key schedule context */
     691:     memset(ks_context, 0, sizeof(ks_context));
     692:     ks_context[0] = (unsigned char)(ctx->mode % 256);
     693:     ks_contextlen--; /* remaining space */
     694:     halflen = kdf_info->Nh;
     695:     if ((2 * halflen) > ks_contextlen) {
     696:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     697:         return 0;
     698:     }
     699:     /* check a psk was set if in that mode */
     700:     if (ctx->mode == OSSL_HPKE_MODE_PSK
     701:         || ctx->mode == OSSL_HPKE_MODE_PSKAUTH) {
     702:         if (ctx->psk == NULL || ctx->psklen == 0 || ctx->pskid == NULL) {
     703:             ERR_raise(ERR_LIB_CRYPTO, ERR_R_PASSED_INVALID_ARGUMENT);
     704:             return 0;
     705:         }
     706:     }
