     721:     if (ossl_hpke_labeled_extract(kctx, ks_context + 1, halflen,
     722:             NULL, 0, OSSL_HPKE_SEC51LABEL,
     723:             suitebuf, sizeof(suitebuf),
     724:             OSSL_HPKE_PSKIDHASH_LABEL,
     725:             (unsigned char *)ctx->pskid, pskidlen)
     726:         != 1) {
     727:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     728:         goto err;
     729:     }
     730:     if (ossl_hpke_labeled_extract(kctx, ks_context + 1 + halflen, halflen,
     731:             NULL, 0, OSSL_HPKE_SEC51LABEL,
     732:             suitebuf, sizeof(suitebuf),
     733:             OSSL_HPKE_INFOHASH_LABEL,
     734:             (unsigned char *)info, infolen)
     735:         != 1) {
     736:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     737:         goto err;
     738:     }
     739:     ks_contextlen = 1 + 2 * halflen;
     740:     secretlen = kdf_info->Nh;
     741:     if (secretlen > OSSL_HPKE_MAXSIZE) {
     742:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     743:         goto err;
     744:     }
     745:     if (ossl_hpke_labeled_extract(kctx, secret, secretlen,
     746:             ctx->shared_secret, ctx->shared_secretlen,
     747:             OSSL_HPKE_SEC51LABEL,
     748:             suitebuf, sizeof(suitebuf),
     749:             OSSL_HPKE_SECRET_LABEL,
     750:             ctx->psk, ctx->psklen)
     751:         != 1) {
     752:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     753:         goto err;
     754:     }
     755:     if (ctx->suite.aead_id != OSSL_HPKE_AEAD_ID_EXPORTONLY) {
     756:         /* we only need nonce/key for non export AEADs */
     757:         ctx->noncelen = aead_info->Nn;
     758:         ctx->nonce = OPENSSL_malloc(ctx->noncelen);
     759:         if (ctx->nonce == NULL)
     760:             goto err;
     761:         if (ossl_hpke_labeled_expand(kctx, ctx->nonce, ctx->noncelen,
     762:                 secret, secretlen, OSSL_HPKE_SEC51LABEL,
     763:                 suitebuf, sizeof(suitebuf),
     764:                 OSSL_HPKE_NONCE_LABEL,
     765:                 ks_context, ks_contextlen)
     766:             != 1) {
     767:             ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     768:             goto err;
     769:         }
     770:         ctx->keylen = aead_info->Nk;
     771:         ctx->key = OPENSSL_malloc(ctx->keylen);
     772:         if (ctx->key == NULL)
     773:             goto err;
     774:         if (ossl_hpke_labeled_expand(kctx, ctx->key, ctx->keylen,
     775:                 secret, secretlen, OSSL_HPKE_SEC51LABEL,
     776:                 suitebuf, sizeof(suitebuf),
     777:                 OSSL_HPKE_KEY_LABEL,
     778:                 ks_context, ks_contextlen)
     779:             != 1) {
     780:             ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     781:             goto err;
     782:         }
     783:     }
     784:     ctx->exporterseclen = kdf_info->Nh;
>>   785:     ctx->exportersec = OPENSSL_malloc(ctx->exporterseclen);
     786:     if (ctx->exportersec == NULL)
     787:         goto err;
     788:     if (ossl_hpke_labeled_expand(kctx, ctx->exportersec, ctx->exporterseclen,
     789:             secret, secretlen, OSSL_HPKE_SEC51LABEL,
     790:             suitebuf, sizeof(suitebuf),
     791:             OSSL_HPKE_EXP_LABEL,
     792:             ks_context, ks_contextlen)
     793:         != 1) {
     794:         ERR_raise(ERR_LIB_CRYPTO, ERR_R_INTERNAL_ERROR);
     795:         goto err;
     796:     }
     797:     erv = 1;
     798: 
     799: err:
     800:     OPENSSL_cleanse(ks_context, OSSL_HPKE_MAXSIZE);
     801:     OPENSSL_cleanse(secret, OSSL_HPKE_MAXSIZE);
     802:     EVP_KDF_CTX_free(kctx);
     803:     return erv;
     804: }

