     189: int OSSL_HTTP_REQ_CTX_set_request_line(OSSL_HTTP_REQ_CTX *rctx, int method_POST,
     190:     const char *server, const char *port,
     191:     const char *path)
     192: {
     193:     if (rctx == NULL) {
     194:         ERR_raise(ERR_LIB_HTTP, ERR_R_PASSED_NULL_PARAMETER);
     195:         return 0;
     196:     }
     197:     if (!no_crlf("server", server)
     198:         || !no_crlf("port", port)
     199:         || !no_crlf("path", path))
     200:         return 0;
     201:     BIO_free(rctx->mem);
>>   202:     if ((rctx->mem = BIO_new(BIO_s_mem())) == NULL)
     203:         return 0;
     204: 
     205:     rctx->method_POST = method_POST != 0;
     206:     if (BIO_printf(rctx->mem, "%s ", rctx->method_POST ? "POST" : "GET") <= 0)
     207:         return 0;
     208: 
     209:     if (server != NULL) { /* HTTP (but not HTTPS) proxy is used */
     210:         /*
     211:          * Section 5.1.2 of RFC 1945 states that the absoluteURI form is only
     212:          * allowed when using a proxy
     213:          */
     214:         if (BIO_printf(rctx->mem, OSSL_HTTP_PREFIX "%s", server) <= 0)
     215:             return 0;
     216:         if (port != NULL && BIO_printf(rctx->mem, ":%s", port) <= 0)
     217:             return 0;
     218:     }
     219: 
     220:     /* Make sure path includes a forward slash (abs_path) */
     221:     if (path == NULL) {
     222:         path = "/";
     223:     } else if (HAS_PREFIX(path, "http://")) { /* absoluteURI for proxy use */
     224:         if (server != NULL) {
     225:             ERR_raise(ERR_LIB_HTTP, ERR_R_PASSED_INVALID_ARGUMENT);
     226:             return 0;
     227:         }
     228:     } else if (path[0] != '/' && BIO_printf(rctx->mem, "/") <= 0) {
     229:         return 0;
     230:     }
     231:     /*
     232:      * Add (the rest of) the path and the HTTP version,
     233:      * which is fixed to 1.0 for straightforward implementation of keep-alive
     234:      */
     235:     if (BIO_printf(rctx->mem, "%s " HTTP_1_0 "\r\n", path) <= 0)
     236:         return 0;
     237: 
     238:     rctx->resp_len = 0;
     239:     rctx->state = OHS_ADD_HEADERS;
     240:     return 1;
     241: }

