     351: static int ASIdentifierChoice_canonize(ASIdentifierChoice *choice)
     352: {
     353:     ASN1_INTEGER *a_max_plus_one = NULL;
     354:     ASN1_INTEGER *orig;
     355:     BIGNUM *bn = NULL;
     356:     int i, ret = 0;
     357: 
     358:     /*
     359:      * Nothing to do for empty element or inheritance.
     360:      */
     361:     if (choice == NULL || choice->type == ASIdentifierChoice_inherit)
     362:         return 1;
     363: 
     364:     /*
     365:      * If not a list, or if empty list, it's broken.
     366:      */
     367:     if (choice->type != ASIdentifierChoice_asIdsOrRanges || sk_ASIdOrRange_num(choice->u.asIdsOrRanges) == 0) {
     368:         ERR_raise(ERR_LIB_X509V3, X509V3_R_EXTENSION_VALUE_ERROR);
     369:         return 0;
     370:     }
     371: 
     372:     /*
     373:      * We have a non-empty list.  Sort it.
     374:      */
     375:     sk_ASIdOrRange_sort(choice->u.asIdsOrRanges);
     376: 
     377:     /*
     378:      * Now check for errors and suboptimal encoding, rejecting the
     379:      * former and fixing the latter.
     380:      */
     381:     for (i = 0; i < sk_ASIdOrRange_num(choice->u.asIdsOrRanges) - 1; i++) {
     382:         ASIdOrRange *a = sk_ASIdOrRange_value(choice->u.asIdsOrRanges, i);
     383:         ASIdOrRange *b = sk_ASIdOrRange_value(choice->u.asIdsOrRanges, i + 1);
     384:         ASN1_INTEGER *a_min = NULL, *a_max = NULL, *b_min = NULL, *b_max = NULL;
     385: 
     386:         if (!extract_min_max(a, &a_min, &a_max)
     387:             || !extract_min_max(b, &b_min, &b_max))
     388:             goto done;
     389: 
     390:         /*
     391:          * Make sure we're properly sorted (paranoia).
     392:          */
     393:         if (!ossl_assert(ASN1_INTEGER_cmp(a_min, b_min) <= 0))
     394:             goto done;
     395: 
     396:         /*
     397:          * Punt inverted ranges.
     398:          */
     399:         if (ASN1_INTEGER_cmp(a_min, a_max) > 0 || ASN1_INTEGER_cmp(b_min, b_max) > 0)
     400:             goto done;
     401: 
     402:         /*
     403:          * Check for overlaps.
     404:          */
     405:         if (ASN1_INTEGER_cmp(a_max, b_min) >= 0) {
     406:             ERR_raise(ERR_LIB_X509V3, X509V3_R_EXTENSION_VALUE_ERROR);
     407:             goto done;
     408:         }
     409: 
     410:         /*
     411:          * Calculate a_max + 1 to check for adjacency.
     412:          */
     413:         if ((bn == NULL && (bn = BN_new()) == NULL) || ASN1_INTEGER_to_BN(a_max, bn) == NULL || !BN_add_word(bn, 1)) {
     414:             ERR_raise(ERR_LIB_X509V3, ERR_R_BN_LIB);
     415:             goto done;
     416:         }
     417: 
     418:         if ((a_max_plus_one = BN_to_ASN1_INTEGER(bn, orig = a_max_plus_one)) == NULL) {
     419:             a_max_plus_one = orig;
     420:             ERR_raise(ERR_LIB_X509V3, ERR_R_ASN1_LIB);
     421:             goto done;
     422:         }
     423: 
     424:         /*
     425:          * If a and b are adjacent, merge them.
     426:          */
     427:         if (ASN1_INTEGER_cmp(a_max_plus_one, b_min) == 0) {
     428:             ASRange *r;
     429:             switch (a->type) {
     430:             case ASIdOrRange_id:
>>   431:                 if ((r = OPENSSL_malloc(sizeof(*r))) == NULL)
     432:                     goto done;
     433:                 r->min = a_min;
     434:                 r->max = b_max;
     435:                 a->type = ASIdOrRange_range;
     436:                 a->u.range = r;
     437:                 break;
     438:             case ASIdOrRange_range:
     439:                 ASN1_INTEGER_free(a->u.range->max);
     440:                 a->u.range->max = b_max;
     441:                 break;
     442:             }
     443:             switch (b->type) {
     444:             case ASIdOrRange_id:
     445:                 b->u.id = NULL;
     446:                 break;
     447:             case ASIdOrRange_range:
     448:                 b->u.range->max = NULL;
     449:                 break;
     450:             }
     451:             ASIdOrRange_free(b);
     452:             (void)sk_ASIdOrRange_delete(choice->u.asIdsOrRanges, i + 1);
     453:             i--;
     454:             continue;
     455:         }
     456:     }
     457: 
     458:     /*
     459:      * Check for final inverted range.
     460:      */
     461:     i = sk_ASIdOrRange_num(choice->u.asIdsOrRanges) - 1;
     462:     {
     463:         ASIdOrRange *a = sk_ASIdOrRange_value(choice->u.asIdsOrRanges, i);
     464:         ASN1_INTEGER *a_min, *a_max;
     465:         if (a != NULL && a->type == ASIdOrRange_range) {
     466:             if (!extract_min_max(a, &a_min, &a_max)
     467:                 || ASN1_INTEGER_cmp(a_min, a_max) > 0)
     468:                 goto done;
     469:         }
     470:     }
     471: 
     472:     /* Paranoia */
     473:     if (!ossl_assert(ASIdentifierChoice_is_canonical(choice)))
     474:         goto done;
     475: 
     476:     ret = 1;
     477: 
     478: done:
     479:     ASN1_INTEGER_free(a_max_plus_one);
     480:     BN_free(bn);
     481:     return ret;
     482: }

