     360:                 }
     361:                 not->noticeref = nref;
     362:             } else
     363:                 nref = not->noticeref;
     364:             nos = X509V3_parse_list(cnf->value);
     365:             if (!nos || !sk_CONF_VALUE_num(nos)) {
