      67: static int set_dist_point_name(DIST_POINT_NAME **pdp, X509V3_CTX *ctx,
      68:     CONF_VALUE *cnf)
      69: {
      70:     STACK_OF(GENERAL_NAME) *fnm = NULL;
      71:     STACK_OF(X509_NAME_ENTRY) *rnm = NULL;
      72: 
      73:     if (cnf->value == NULL) {
      74:         ERR_raise(ERR_LIB_X509V3, X509V3_R_MISSING_VALUE);
      75:         goto err;
      76:     }
      77: 
      78:     if (HAS_PREFIX(cnf->name, "fullname")) {
      79:         fnm = gnames_from_sectname(ctx, cnf->value);
      80:         if (!fnm)
      81:             goto err;
      82:     } else if (strcmp(cnf->name, "relativename") == 0) {
      83:         int ret;
      84:         STACK_OF(CONF_VALUE) *dnsect;
      85:         X509_NAME *nm;
      86:         nm = X509_NAME_new();
      87:         if (nm == NULL)
      88:             return -1;
      89:         dnsect = X509V3_get_section(ctx, cnf->value);
      90:         if (!dnsect) {
      91:             X509_NAME_free(nm);
      92:             ERR_raise(ERR_LIB_X509V3, X509V3_R_SECTION_NOT_FOUND);
      93:             return -1;
      94:         }
      95:         ret = X509V3_NAME_from_section(nm, dnsect, MBSTRING_ASC);
      96:         X509V3_section_free(ctx, dnsect);
      97:         rnm = nm->entries;
      98:         nm->entries = NULL;
      99:         X509_NAME_free(nm);
     100:         if (!ret || sk_X509_NAME_ENTRY_num(rnm) <= 0)
     101:             goto err;
     102:         /*
     103:          * Since its a name fragment can't have more than one RDNSequence
     104:          */
     105:         if (sk_X509_NAME_ENTRY_value(rnm,
     106:                 sk_X509_NAME_ENTRY_num(rnm) - 1)
     107:                 ->set) {
     108:             ERR_raise(ERR_LIB_X509V3, X509V3_R_INVALID_MULTIPLE_RDNS);
     109:             goto err;
     110:         }
     111:     } else
     112:         return 0;
     113: 
     114:     if (*pdp) {
     115:         ERR_raise(ERR_LIB_X509V3, X509V3_R_DISTPOINT_ALREADY_SET);
     116:         goto err;
     117:     }
     118: 
>>   119:     *pdp = DIST_POINT_NAME_new();
     120:     if (*pdp == NULL)
     121:         goto err;
     122:     if (fnm) {
     123:         (*pdp)->type = 0;
     124:         (*pdp)->name.fullname = fnm;
     125:     } else {
     126:         (*pdp)->type = 1;
     127:         (*pdp)->name.relativename = rnm;
     128:     }
     129: 
     130:     return 1;
     131: 
     132: err:
     133:     sk_GENERAL_NAME_pop_free(fnm, GENERAL_NAME_free);
     134:     sk_X509_NAME_ENTRY_pop_free(rnm, X509_NAME_ENTRY_free);
     135:     return -1;
     136: }

