     333: static int ech_decode_one_entry(OSSL_ECHSTORE_ENTRY **rent, PACKET *pkt,
     334:     EVP_PKEY *priv, int for_retry)
     335: {
     336:     size_t ech_content_length = 0;
     337:     unsigned int tmpi;
     338:     const unsigned char *tmpecp = NULL;
     339:     size_t tmpeclen = 0, test_publen = 0;
     340:     PACKET ver_pkt, pub_pkt, cipher_suites, public_name_pkt, exts;
     341:     uint16_t thiskemid;
     342:     size_t suiteoctets = 0;
     343:     unsigned int ci = 0;
     344:     unsigned char cipher[OSSL_ECH_CIPHER_LEN], max_name_len;
     345:     unsigned char test_pub[OSSL_ECH_CRYPTO_VAR_SIZE];
     346:     OSSL_ECHSTORE_ENTRY *ee = NULL;
     347: 
     348:     if (rent == NULL) {
     349:         ERR_raise(ERR_LIB_SSL, ERR_R_INTERNAL_ERROR);
     350:         return 0;
     351:     }
     352:     if (pkt == NULL) {
     353:         ERR_raise(ERR_LIB_SSL, ERR_R_INTERNAL_ERROR);
     354:         goto err;
     355:     }
     356:     ee = OPENSSL_zalloc(sizeof(*ee));
     357:     if (ee == NULL)
     358:         goto err;
     359:     /* note start of encoding so we can make a copy later */
     360:     tmpeclen = PACKET_remaining(pkt);
     361:     if (PACKET_peek_bytes(pkt, &tmpecp, tmpeclen) != 1
     362:         || !PACKET_get_net_2(pkt, &tmpi)) {
     363:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     364:         goto err;
     365:     }
     366:     ee->version = (uint16_t)tmpi;
     367: 
     368:     /* grab versioned packet data */
     369:     if (!PACKET_get_length_prefixed_2(pkt, &ver_pkt)) {
     370:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     371:         goto err;
     372:     }
     373:     ech_content_length = (unsigned int)PACKET_remaining(&ver_pkt);
     374:     switch (ee->version) {
     375:     case OSSL_ECH_RFC9849_VERSION:
     376:         break;
     377:     default:
     378:         /* skip over in case we get something we can handle later */
     379:         if (!PACKET_forward(&ver_pkt, ech_content_length)) {
     380:             ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     381:             goto err;
     382:         }
     383:         /* nothing to return but not a fail */
     384:         ossl_echstore_entry_free(ee);
     385:         *rent = NULL;
     386:         return 1;
     387:     }
     388:     if (!PACKET_copy_bytes(&ver_pkt, &ee->config_id, 1)
     389:         || !PACKET_get_net_2(&ver_pkt, &tmpi)
     390:         || !PACKET_get_length_prefixed_2(&ver_pkt, &pub_pkt)
     391:         || !PACKET_memdup(&pub_pkt, &ee->pub, &ee->pub_len)
     392:         || !PACKET_get_length_prefixed_2(&ver_pkt, &cipher_suites)
     393:         || (suiteoctets = PACKET_remaining(&cipher_suites)) <= 0
     394:         || (suiteoctets % 2) == 1
     395:         || suiteoctets / OSSL_ECH_CIPHER_LEN > UINT_MAX) {
     396:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     397:         goto err;
     398:     }
     399:     thiskemid = (uint16_t)tmpi;
     400:     ee->nsuites = (unsigned int)(suiteoctets / OSSL_ECH_CIPHER_LEN);
>>   401:     ee->suites = OPENSSL_malloc_array(ee->nsuites, sizeof(*ee->suites));
     402:     if (ee->suites == NULL)
     403:         goto err;
     404:     while (PACKET_copy_bytes(&cipher_suites, cipher,
     405:         OSSL_ECH_CIPHER_LEN)) {
     406:         ee->suites[ci].kem_id = thiskemid;
     407:         ee->suites[ci].kdf_id = cipher[0] << 8 | cipher[1];
     408:         ee->suites[ci].aead_id = cipher[2] << 8 | cipher[3];
     409:         if (ci++ >= ee->nsuites) {
     410:             ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     411:             goto err;
     412:         }
     413:     }
     414:     if (PACKET_remaining(&cipher_suites) > 0
     415:         || !PACKET_copy_bytes(&ver_pkt, &max_name_len, 1)) {
     416:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     417:         goto err;
     418:     }
     419:     ee->max_name_length = max_name_len;
     420:     if (!PACKET_get_length_prefixed_1(&ver_pkt, &public_name_pkt)) {
     421:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     422:         goto err;
     423:     }
     424:     if (PACKET_contains_zero_byte(&public_name_pkt)
     425:         || PACKET_remaining(&public_name_pkt) < TLSEXT_MINLEN_host_name
     426:         || !PACKET_strndup(&public_name_pkt, &ee->public_name)) {
     427:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     428:         goto err;
     429:     }
     430:     /*
     431:      * We don't really handle ECHConfig extensions as of now,
     432:      * (none are well-defined), so we're only skipping over
     433:      * whatever we find here. If/when adding real extensions
     434:      * then it may be necessary to also check that the set of
     435:      * extensions loaded contain no duplicate types.
     436:      */
     437:     if (!PACKET_get_length_prefixed_2(&ver_pkt, &exts)) {
     438:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     439:         goto err;
     440:     }
     441:     if (PACKET_remaining(&exts) > 0
     442:         && ech_decode_echconfig_exts(ee, &exts) != 1) {
     443:         ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     444:         goto err;
     445:     }
     446:     /* set length of encoding of this ECHConfig */
     447:     ee->encoded_len = PACKET_data(&ver_pkt) - tmpecp;
     448:     /* copy encoded as it might get free'd if a reduce happens */
     449:     ee->encoded = OPENSSL_memdup(tmpecp, ee->encoded_len);
     450:     if (ee->encoded == NULL)
     451:         goto err;
     452:     if (priv != NULL) {
     453:         if (EVP_PKEY_get_octet_string_param(priv,
     454:                 OSSL_PKEY_PARAM_ENCODED_PUBLIC_KEY,
     455:                 test_pub, OSSL_ECH_CRYPTO_VAR_SIZE,
     456:                 &test_publen)
     457:             != 1) {
     458:             ERR_raise(ERR_LIB_SSL, SSL_R_ECH_DECODE_ERROR);
     459:             goto err;
     460:         }
     461:         if (test_publen == ee->pub_len
     462:             && !memcmp(test_pub, ee->pub, ee->pub_len)) {
     463:             EVP_PKEY_up_ref(priv); /* associate the private key */
     464:             ee->keyshare = priv;
     465:             ee->for_retry = for_retry;
     466:         }
     467:     }
     468:     ee->loadtime = time(0);
     469:     *rent = ee;
     470:     return 1;
     471: err:
     472:     ossl_echstore_entry_free(ee);
     473:     *rent = NULL;
     474:     return 0;
     475: }

