     771: STACK_OF(X509_NAME) *SSL_load_client_CA_file_ex(const char *file,
     772:     OSSL_LIB_CTX *libctx,
     773:     const char *propq)
     774: {
     775:     BIO *in = BIO_new(BIO_s_file());
     776:     X509 *x = NULL;
     777:     const X509_NAME *cxn = NULL;
     778:     X509_NAME *xn = NULL;
     779:     STACK_OF(X509_NAME) *ret = NULL;
     780:     LHASH_OF(X509_NAME) *name_hash = lh_X509_NAME_new(xname_hash, xname_cmp);
     781:     OSSL_LIB_CTX *prev_libctx = NULL;
     782: 
     783:     if (file == NULL) {
     784:         ERR_raise(ERR_LIB_SSL, ERR_R_PASSED_NULL_PARAMETER);
     785:         goto err;
     786:     }
     787:     if (name_hash == NULL) {
     788:         ERR_raise(ERR_LIB_SSL, ERR_R_CRYPTO_LIB);
     789:         goto err;
     790:     }
     791:     if (in == NULL) {
     792:         ERR_raise(ERR_LIB_SSL, ERR_R_BIO_LIB);
     793:         goto err;
     794:     }
     795: 
>>   796:     x = X509_new_ex(libctx, propq);
     797:     if (x == NULL) {
     798:         ERR_raise(ERR_LIB_SSL, ERR_R_X509_LIB);
     799:         goto err;
     800:     }
     801:     if (BIO_read_filename(in, file) <= 0)
     802:         goto err;
     803: 
     804:     /* Internally lh_X509_NAME_retrieve() needs the libctx to retrieve SHA1 */
     805:     prev_libctx = OSSL_LIB_CTX_set0_default(libctx);
     806:     for (;;) {
     807:         if (PEM_read_bio_X509(in, &x, NULL, NULL) == NULL)
     808:             break;
     809:         if (ret == NULL) {
     810:             ret = sk_X509_NAME_new_null();
     811:             if (ret == NULL) {
     812:                 ERR_raise(ERR_LIB_SSL, ERR_R_CRYPTO_LIB);
     813:                 goto err;
     814:             }
     815:         }
     816:         if ((cxn = X509_get_subject_name(x)) == NULL)
     817:             goto err;
     818:         /* check for duplicates */
     819:         xn = X509_NAME_dup(cxn);
     820:         if (xn == NULL)
     821:             goto err;
     822:         if (lh_X509_NAME_retrieve(name_hash, xn) != NULL) {
     823:             /* Duplicate. */
     824:             X509_NAME_free(xn);
     825:             xn = NULL;
     826:         } else {
     827:             lh_X509_NAME_insert(name_hash, xn);
     828:             if (!sk_X509_NAME_push(ret, xn))
     829:                 goto err;
     830:         }
     831:     }
     832:     goto done;
     833: 
     834: err:
     835:     X509_NAME_free(xn);
     836:     sk_X509_NAME_pop_free(ret, X509_NAME_free);
     837:     ret = NULL;
     838: done:
     839:     /* restore the old libctx */
     840:     OSSL_LIB_CTX_set0_default(prev_libctx);
     841:     BIO_free(in);
     842:     X509_free(x);
     843:     lh_X509_NAME_free(name_hash);
     844:     if (ret != NULL)
     845:         ERR_clear_error();
     846:     return ret;
     847: }

