     689:         goto failure;
     690:     }
     691: 
     692:     /*
     693:      * We limit the number of key shares we are willing to process to
     694:      * MAX_KEY_SHARES regardless of whether we include them in keyshares_arr or
     695:      * not.
     696:      */
